import pandas as pddef select_best_spectrum(input_csv, snr_column, output_file='best_spectrum.csv'):       try:        # Load the master CSV file        df = pd.read_csv(input_csv)        print(f"Loaded {len(df)} spectra.")        # Find the index of the row with the maximum SNR        df[snr_column] = pd.to_numeric(df[snr_column])        best_spectrum_idx = df[snr_column].idxmax()        # Extract the row with the highest SNR        best_spectrum = df.loc[[best_spectrum_idx]]        print(f"Best spectrum found with SNR: {best_spectrum[snr_column].values[0]}")        # Save to a new CSV        best_spectrum.to_csv(output_file, index=False)        print(f"Best spectrum saved to {output_file}")    except Exception as e:        print(f"Error: {e}")# Run select_best_spectrum('Carmen_master_spectra.csv', 'SNR_General')